<script setup lang="ts">
import {computed,onMounted} from 'vue';
import TrendChart from './TrendChart.vue';
import {warehouses,inspectionAdvice,storageOverdue} from '@/data/safety/warehouse';
import {formatDate,formatTime} from '@/utils/safety/format';
import type {SafetyBridge} from '@/composables/useSafetyBridge';
const props=defineProps<{store:SafetyBridge}>();
const selected=computed(()=>props.store.selectedDevice.value.stack ? props.store.selectedDevice.value : props.store.state.devices.find(d=>d.id==='WH-A-A01')!);
const warehouseId=computed(()=>selected.value.stack!.warehouseId);
const currentId=computed(()=>selected.value.id);
const stacks=computed(()=>props.store.state.devices.filter(d=>d.stack?.warehouseId===warehouseId.value));
const warehouse=computed(()=>warehouses.find(w=>w.id===warehouseId.value)!);
const advice=computed(()=>inspectionAdvice(selected.value,props.store.state.time));
const overdue=computed(()=>storageOverdue(selected.value,props.store.state.time));
const peak=computed(()=>Math.max(...stacks.value.map(d=>d.value)).toFixed(1));
const tasks=computed(()=>stacks.value.filter(d=>inspectionAdvice(d,props.store.state.time).due || storageOverdue(d,props.store.state.time)));
const selectedAlarms=computed(()=>props.store.activeAlarms.value.filter(a=>a.deviceId===currentId.value));
const selectedAlarm=computed(()=>selectedAlarms.value.find(a=>a.severity==='critical') || selectedAlarms.value[0]);
const alarmStatus=computed(()=>!selectedAlarm.value ? '当前垛位无未解除告警' : `${selectedAlarm.value.severity==='critical'?'红色报警':'黄色预警'} · ${selectedAlarm.value.clearedAt?'待人工复核':selectedAlarm.value.acknowledgedAt?'处置跟进中':'待确认'}`);
function chooseWarehouse(id:string){choose(`WH-${id}-A01`);}
function choose(id:string){props.store.selectDevice(id);}
function color(value:number){return value>=35?'#ef5561':value>=32?'#e7b845':`hsl(${207-(value-25)*10} 78% ${37+(value-25)*2}%)`;}
function inject(kind:'high'|'critical'|'normal'){props.store.injectScenario(kind,selected.value.id);}
onMounted(()=>choose(currentId.value));
</script>
<template>
  <div class="warehouse-board">
    <div class="warehouse-cards"><button v-for="w in warehouses" :key="w.id" :class="{selected:warehouseId===w.id}" @click="chooseWarehouse(w.id)"><span class="warehouse-letter">{{w.id}}</span><span><b>{{w.name}}</b><small>{{w.use}}</small></span><span class="warehouse-env"><b>{{w.ambient.toFixed(1)}}<em>℃</em></b><small>{{w.humidity}}% RH · 48垛</small></span></button></div>
    <div class="warehouse-body">
      <div class="warehouse-events"><slot/></div>
      <section class="stack-detail screen-panel"><header><h2><i/>垛位档案 / 温度趋势</h2><span>{{selected.stack!.batch}}</span></header>
        <div class="stack-reading"><div><small>{{selected.name}} · {{selected.stack!.material}}</small><strong>{{selected.value.toFixed(1)}}<em>℃</em></strong></div><span :class="{attention:advice.due}">{{advice.label}}<small>{{advice.due?'温检已到期':'温检未到期'}}</small></span><span>温差<strong :class="{red:selected.value-selected.stack!.ambient>4}">{{selected.value>=selected.stack!.ambient?'+':''}}{{(selected.value-selected.stack!.ambient).toFixed(1)}}℃</strong></span></div>
        <p class="stack-alarm-status" :class="selectedAlarm?.severity" role="status">{{alarmStatus}}</p>
        <div class="stack-facts"><span>环境温湿度<b>{{selected.stack!.ambient}}℃ / {{selected.stack!.humidity}}%RH</b></span><span>入库日期<b>{{formatDate(selected.stack!.storedAt)}}</b></span><span>最近温检<b>{{formatDate(selected.stack!.checkedAt)}} {{formatTime(selected.stack!.checkedAt,false)}}</b></span><span>存放状态<b :class="{red:overdue}">{{overdue?'备料库存放超过1个月':'在库跟踪中'}}</b></span></div>
        <div class="stack-chart"><TrendChart :device="selected" :minutes="6" :show-thresholds="true"/></div>
        <label class="stack-exception"><input type="checkbox" :checked="selected.stack!.ambientException" @change="store.setStackException(selected.id,($event.target as HTMLInputElement).checked)"/>环境异常变温 / 高温天气入库（模拟核验条件）</label>
        <div class="stack-actions"><button @click="inject('high')">模拟升温</button><button class="danger" @click="inject('critical')">模拟温差异常</button><button @click="inject('normal')">恢复</button><button @click="store.recordInspection(selected.id)">登记温检</button></div>
      </section>
    </div>
      <section class="warehouse-map screen-panel">
        <header><h2><i/>库房 / 垛位温度热力图</h2><span>模拟实时抽检均值 · 点击垛位查看趋势</span></header>
        <div class="warehouse-map-meta"><b>{{warehouse.name}}</b><span>最高包心 {{peak}}℃</span><span>{{tasks.length}}项温检 / 存放提醒</span><span class="map-direction">北 ↑</span></div>
        <div class="warehouse-tasks"><button v-for="task in [...tasks].sort((a,b)=>Number(storageOverdue(b,store.state.time))-Number(storageOverdue(a,store.state.time))).slice(0,2)" :key="task.id" @click="choose(task.id)">{{task.name}} · {{storageOverdue(task,store.state.time)?'备料存放超期':'温检到期'}} →</button><span>检查安排：按垛位、原料批次跟踪</span></div>
        <div class="heatmap-wrap"><div class="row-labels"><span v-for="r in ['F','E','D','C','B','A']" :key="r">{{r}}排</span></div><div class="heatmap" role="group" aria-label="垛位温度热力图"><template v-for="r in ['F','E','D','C','B','A']" :key="r"><button v-for="d in stacks.filter(s=>s.stack!.row===r)" :key="d.id" :style="{background:color(d.value)}" :class="{picked:d.id===currentId,hot:d.value>=32,'inspection-due':inspectionAdvice(d,store.state.time).due}" :aria-label="`${d.name} 包心${d.value.toFixed(1)}摄氏度${inspectionAdvice(d,store.state.time).due?'，温检到期':''}`" :aria-pressed="d.id===currentId" :title="`${d.name} · ${d.stack!.batch}${inspectionAdvice(d,store.state.time).due?' · 温检到期':''}`" @click="choose(d.id)"><b>{{d.value.toFixed(1)}}</b><small>{{d.stack!.row}}{{String(d.stack!.column).padStart(2,'0')}}</small><i v-if="inspectionAdvice(d,store.state.time).due" class="inspection-marker" aria-hidden="true">检</i></button></template></div></div>
        <div class="column-labels"><span v-for="col in 8" :key="col">{{col}}列</span></div>
        <footer><span>包心温度 / ℃</span><i class="heat-legend"/><span>24</span><span>32</span><span>35+</span><small>32/35℃对应检查加密，非工艺超温定值</small></footer>
      </section>
  </div>
</template>
<style scoped>
.warehouse-board{height:100%;min-height:0;display:grid;grid-template-rows:clamp(44px,5.8vh,53px) minmax(0,1.08fr) minmax(0,.92fr);gap:8px;color:#b5d7eb}
