.warehouse-events{min-height:0;display:flex;overflow:hidden}.warehouse-events :deep(.ps-alert-table){flex:1;min-width:0;height:100%}.warehouse-body{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(340px,1fr);gap:10px;min-height:0}.screen-panel{min-height:0;border:1px solid #226185;background:linear-gradient(120deg,#0c243b,#071729);box-shadow:inset 0 0 28px #0e4b6c25;position:relative}.screen-panel:before{content:'';position:absolute;left:0;top:-1px;width:32px;height:2px;background:#2de5ff}.screen-panel header{display:flex;justify-content:space-between;align-items:center;padding:0 12px;min-height:33px;border-bottom:1px solid #23516d}.screen-panel h2{display:flex;align-items:center;gap:7px;font-size:12px;letter-spacing:1px;color:#d5eeff}.screen-panel h2 i{display:inline-block;width:3px;height:11px;background:#20d7fc;box-shadow:0 0 6px #20d7fc}.screen-panel header>span{font-size:9px;color:#6b99b9}
.warehouse-map{display:flex;flex-direction:column;padding-bottom:6px}.warehouse-map-meta{display:flex;gap:20px;align-items:center;padding:8px 12px;color:#80adca;font-size:10px}.warehouse-map-meta b{color:#31d5f5;font-weight:500}.map-direction{margin-left:auto}.heatmap-wrap{display:flex;flex:1;min-height:0;padding:0 12px 0 6px;gap:7px}.row-labels{width:22px;display:grid;grid-template-rows:repeat(6,1fr);font-size:9px;color:#77a1bd;text-align:center;align-items:center}.heatmap{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));grid-template-rows:repeat(6,minmax(0,1fr));gap:2px;flex:1;min-height:0}.heatmap button{position:relative;border:1px solid #45a8de25;color:#e8ffff;display:flex;align-items:center;justify-content:center;gap:5px;padding:1px;min-height:0;transition:background .8s}.heatmap b{font:11px Consolas}.heatmap small{font:8px Consolas;opacity:.65}.heatmap button.picked{outline:2px solid #d8fb53;outline-offset:-2px;z-index:1}.heatmap button.hot{color:#152535}.heatmap button:hover{filter:brightness(1.25)}.heatmap button.inspection-due{box-shadow:inset 0 0 0 1px #ffd15a}.inspection-marker{position:absolute;top:2px;right:2px;min-width:15px;height:15px;display:grid;place-items:center;padding:0 2px;background:#ffe083;color:#382808;border-radius:2px;font:700 9px/1 Consolas,serif;font-style:normal;box-shadow:0 1px 4px #07152280}.column-labels{display:grid;grid-template-columns:repeat(8,1fr);padding:4px 12px 0 35px;text-align:center;font-size:9px;color:#719fb9}.warehouse-map footer{display:flex;justify-content:center;align-items:center;gap:9px;padding-top:5px;font-size:9px;color:#85aabe}.heat-legend{width:80px;height:5px;background:linear-gradient(90deg,#1c66c1,#1cc7e0,#e8c655,#ef5561)}.warehouse-map footer small{font-size:8px;color:#5e91ac;margin-left:10px}
.warehouse-tasks{display:flex;gap:10px;padding:0 12px 6px;font-size:9px;color:#638da6;align-items:center}.warehouse-tasks button{font-size:9px;border:0;background:transparent;color:#e4b960;padding:0}.warehouse-tasks>span{margin-left:auto}
.stack-exception{display:flex;align-items:center;gap:6px;font-size:9px;color:#80a8bb;padding:4px 11px}.stack-exception input{width:11px;height:11px;accent-color:#25c8ef}
.stack-detail{display:flex;flex-direction:column}.stack-reading{display:flex;justify-content:space-between;align-items:center;padding:8px 12px;gap:12px}.stack-reading small{display:block;font-size:10px;color:#8db9d0}.stack-reading strong{display:block;font:27px Consolas;color:#8cefff;margin-top:2px}.stack-reading em{font-size:12px;font-style:normal;margin-left:5px}.stack-reading>span{font-size:10px;color:#81c6c4}.stack-reading>span strong{font-size:16px}.stack-reading>span small{font-size:9px;margin-top:5px}.stack-reading .attention{color:#f6c64c}.stack-facts{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0 12px 8px}.stack-facts span{font-size:9px;color:#6592ab}.stack-facts b{display:block;font-size:10px;font-weight:400;color:#b2d2e0;margin-top:4px}.red{color:#ff7885!important}.stack-chart{flex:1;min-height:65px}.stack-chart :deep(.ps-trend-chart){height:100%;padding:0 6px}.stack-actions{display:flex;gap:5px;padding:6px 10px;border-top:1px solid #22465e}.stack-actions button{flex:1;font-size:9px;white-space:nowrap;padding:5px 4px;background:#123852;border:1px solid #2c6981;color:#7ed4e7}.stack-actions .danger{color:#ff9ba1;border-color:#885163;background:#53283840}
.stack-alarm-status{margin:0 12px 8px;padding:5px 8px;font-size:10px;color:#80b9c4;background:#12384c55;border:1px solid #27516b}.stack-alarm-status.warning{color:#f4cd6c;border-color:#9a773b}.stack-alarm-status.critical{color:#ff8c98;border-color:#a14e60}
@media(min-width:1001px) and (max-height:850px){.stack-detail header{min-height:28px}.stack-reading{padding:3px 10px}.stack-reading strong{font-size:23px;margin-top:0}.stack-reading small{font-size:9px}.stack-alarm-status{margin-bottom:3px;padding:3px 7px}.stack-facts{gap:4px 7px;padding-bottom:3px}.stack-facts b{margin-top:2px;font-size:9px}.stack-chart{flex:0 1 30px;min-height:30px}.stack-chart :deep(.ps-trend-chart){height:30px}.stack-exception{padding:2px 9px;font-size:8px}.stack-actions{padding:3px 8px}.stack-actions button{padding:3px 2px;font-size:8px}}
@media(max-width:1000px){.warehouse-board{height:auto;display:block}.warehouse-cards{margin-bottom:10px;grid-template-columns:repeat(2,1fr)}.warehouse-body{grid-template-columns:1fr}.warehouse-map{height:300px;margin-top:10px}.warehouse-events{height:300px}.stack-detail{height:340px}.warehouse-cards button{min-height:60px}}
</style>

